export type EnrollmentStatusType = 
  | 'AUTOENROLLED' 
  | 'ENROLLED' 
  | 'UN-ENROLLED' 
  | 'OPTED_OUT' 
  | 'OPTED_IN' 
  | 'NOT_ENROLLED'
  | 'PENDING_VERIFICATION'
  | 'SUSPENDED'
  | 'RATE_LIMITED';

export type SystemHealthState = 'OPTIMAL' | 'DEGRADED' | 'CRITICAL' | 'SYNCING' | 'MAINTENANCE';

export type DashboardTab = 'overview' | 'api-ledger' | 'diagnostics' | 'security' | 'payload-inspector';

export interface EnrollmentResponse {
  enrollment: {
    enrollmentStatusName: EnrollmentStatusType;
    enrollmentStatusDate: string;
    subStatus?: string;
    eligibilityCode?: string;
    channelId?: string;
  };
  product: {
    merchantDefinedProductCode: string;
    productCategory?: string;
    rewardProgramId?: string;
    pointsBalance?: number;
    redemptionRate?: number;
  };
  metadata?: {
    gatewayTransactionId?: string;
    latencyMs?: number;
    apiVersion?: string;
    routedRegion?: string;
  };
}

export interface ApiLogEntry {
  id: string;
  timestamp: string;
  level: 'INFO' | 'SUCCESS' | 'WARN' | 'ERROR' | 'DEBUG';
  method: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
  endpoint: string;
  statusCode: number;
  latencyMs: number;
  message: string;
  payload?: Record<string, unknown> | null;
  responsePreview?: Record<string, unknown> | null;
}

export interface SystemMetrics {
  totalRequests: number;
  successRate: number;
  avgLatencyMs: number;
  activeHandshakes: number;
  circuitBreakerStatus: 'CLOSED' | 'HALF_OPEN' | 'OPEN';
  rateLimitRemaining: number;
  tlsVersion: string;
}

export interface DashboardConfiguration {
  autoRefreshEnabled: boolean;
  refreshIntervalMs: number;
  environment: 'sandbox' | 'development' | 'production';
  mockLatencyMs: number;
  enableVerboseLogging: boolean;
  strictTlsValidation: boolean;
}

export interface DashboardState {
  status: 'LOADING' | 'ACTIVE' | 'ERROR' | 'DEGRADED' | 'MAINTENANCE';
  data: EnrollmentResponse | null;
  logs: ApiLogEntry[];
  isProcessing: boolean;
  activeTab: DashboardTab;
  metrics: SystemMetrics;
  config: DashboardConfiguration;
  selectedLogId: string | null;
  searchQuery: string;
  filterLevel: string;
  gatewayEndpoint: string;
}

export type DashboardAction =
  | { type: 'SET_STATUS'; payload: DashboardState['status'] }
  | { type: 'SET_DATA'; payload: EnrollmentResponse | null }
  | { type: 'ADD_LOG'; payload: ApiLogEntry }
  | { type: 'CLEAR_LOGS' }
  | { type: 'SET_PROCESSING'; payload: boolean }
  | { type: 'SET_ACTIVE_TAB'; payload: DashboardTab }
  | { type: 'UPDATE_METRICS'; payload: Partial<SystemMetrics> }
  | { type: 'UPDATE_CONFIG'; payload: Partial<DashboardConfiguration> }
  | { type: 'SELECT_LOG'; payload: string | null }
  | { type: 'SET_SEARCH_QUERY'; payload: string }
  | { type: 'SET_FILTER_LEVEL'; payload: string }
  | { type: 'SET_GATEWAY_ENDPOINT'; payload: string };

