export const initialDashboardState: DashboardState = {
  status: 'LOADING',
  data: null,
  logs: [],
  isProcessing: false,
  activeTab: 'overview',
  metrics: initialSystemMetrics,
  config: initialDashboardConfig,
  selectedLogId: null,
  searchQuery: '',
  filterLevel: 'ALL',
  gatewayEndpoint: '/api/card/loyalty/enrollment',
};

export function dashboardReducer(state: DashboardState, action: DashboardAction): DashboardState {
  switch (action.type) {
    case 'SET_STATUS':
      return { ...state, status: action.payload };
    case 'SET_DATA':
      return { ...state, data: action.payload };
    case 'ADD_LOG':
      return { 
        ...state, 
        logs: [action.payload, ...state.logs].slice(0, 150),
        metrics: {
          ...state.metrics,
          totalRequests: state.metrics.totalRequests + 1,
          avgLatencyMs: Math.round((state.metrics.avgLatencyMs * state.metrics.totalRequests + action.payload.latencyMs) / (state.metrics.totalRequests + 1))
        }
      };
    case 'CLEAR_LOGS':
      return { ...state, logs: [], selectedLogId: null };
    case 'SET_PROCESSING':
      return { ...state, isProcessing: action.payload };
    case 'SET_ACTIVE_TAB':
      return { ...state, activeTab: action.payload };
    case 'UPDATE_METRICS':
      return { ...state, metrics: { ...state.metrics, ...action.payload } };
    case 'UPDATE_CONFIG':
      return { ...state, config: { ...state.config, ...action.payload } };
    case 'SELECT_LOG':
      return { ...state, selectedLogId: action.payload };
    case 'SET_SEARCH_QUERY':
      return { ...state, searchQuery: action.payload };
    case 'SET_FILTER_LEVEL':
      return { ...state, filterLevel: action.payload };
    case 'SET_GATEWAY_ENDPOINT':
      return { ...state, gatewayEndpoint: action.payload };
    default:
      return state;
  }
}

